CREATE TABLE IF NOT EXISTS asset_registry_public_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), passport_id uuid NOT NULL REFERENCES continental_asset_passports(id) ON DELETE CASCADE UNIQUE, public_identifier text NOT NULL UNIQUE, public_status text NOT NULL DEFAULT 'Not Published', verification_code text UNIQUE, qr_payload text, disclosure_level text NOT NULL DEFAULT 'Minimal', public_title text, public_asset_type text, public_country text, public_jurisdiction text, public_location_summary text, passport_version integer, verification_status text NOT NULL DEFAULT 'Unverified', evidence_confidence numeric(6,2), last_verified_at timestamptz, next_review_at timestamptz, public_summary text, public_notes text, published_at timestamptz, published_by_reference text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset_registry_public_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES asset_registry_public_profiles(id) ON DELETE CASCADE, event_type text NOT NULL, public_message text NOT NULL, passport_version integer, verification_reference text, occurred_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'Published');
CREATE TABLE IF NOT EXISTS asset_registry_access_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_identifier text NOT NULL, access_type text NOT NULL DEFAULT 'Public Verification', accessed_at timestamptz NOT NULL DEFAULT now(), result text NOT NULL, reference_hash text);
CREATE INDEX IF NOT EXISTS idx_public_registry_status ON asset_registry_public_profiles(public_status,verification_status);
CREATE INDEX IF NOT EXISTS idx_public_registry_events ON asset_registry_public_events(profile_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_public_registry_access ON asset_registry_access_log(public_identifier,accessed_at DESC);